class BusinessRuleViolation(Exception):
    """Raised when a legacy business rule blocks an operation."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _credit_limit(value: object) -> float:
    """Apply legacy numeric semantics: missing/empty values are zero."""
    if value is None or value == "":
        return 0.0
    return float(value)


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """
    Release an account credit hold according to legacy ACC-004 semantics.

    The supplied account is never modified.
    """
    updated_account = account.copy()

    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _credit_limit(account.get("CRED_LIMIT", "")) <= 0:
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    return updated_account, [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": str(account.get("ACCT_ID", "")),
        }
    ]
